#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"//// Обработка переключателей c тремя состояниями//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  EDirect eDir;  int nShiftMax;  bool bAction;  POINT pt[2][5];  } Queue_Shift;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int PressShift(DefinePress)  {  //  if ( nCode == 0 )    return 0;  //  else  if ( nCode == 1 )    return 0;  //  Queue_Shift* p = (Queue_Shift*)s;  if ( !::PtInRect( &p->mRect, point ) )    return 0;  //  if ( p->bAction )    {    switch ( p->eDir )      {      case dirRight:        q.setShift.x = 0;        ::OffsetRect( &p->mRect, -p->nShiftMax, 0 );        break;      case dirDown:        q.setShift.y = 0;        ::OffsetRect( &p->mRect, 0, -p->nShiftMax );        break;      };    }  else    {    switch ( p->eDir )      {      case dirRight:        q.setShift.x = p->nShiftMax;        ::OffsetRect( &p->mRect, p->nShiftMax, 0 );        break;      case dirDown:        q.setShift.y = p->nShiftMax;        ::OffsetRect( &p->mRect, 0, p->nShiftMax );        break;      };    }  //  if ( q.hWnd != NULL )  ::InvalidateRect( q.hWnd, NULL, FALSE );  p->bAction = !p->bAction;  //  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintShift(DefinePaint)  {  //  QueueP(Queue_Shift);  COLORREF color = 0xffffff;  CMyPen pen( hDC, 0x0040ff );  CMyBrush brs( hDC, color, true );  int n = p->bAction ? 1 : 0;  ::Polygon( hDC, p->pt[n], 5 );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddShift(DefineTegs)  {  //  AddQueueEx(Queue_Shift);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_BUTTON;  // Определение функции вывода  p->paint = &PaintShift;  p->press = &PressShift;  //  p->eDir = dirRight;  //  STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },    { 'N', "d"     , &p->eDir },    { 'N', "dir"   , &p->eDir },    { 'N', "direct", &p->eDir },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  switch ( p->eDir )    {    case dirRight:      {      p->nShiftMax = Atoi(teg[0].value);      int h = (p->mRect.bottom-p->mRect.top)/2;      //      p->pt[0][0].x = p->mRect.left   ;p->pt[0][0].y = p->mRect.top;      p->pt[0][1].x = p->mRect.left   ;p->pt[0][1].y = p->mRect.bottom;      p->pt[0][2].x = p->mRect.right-h;p->pt[0][2].y = p->mRect.bottom;      p->pt[0][3].x = p->mRect.right  ;p->pt[0][3].y = (p->mRect.top+p->mRect.bottom)/2;      p->pt[0][4].x = p->mRect.right-h;p->pt[0][4].y = p->mRect.top;      //      p->pt[1][0].x = p->mRect.right ;p->pt[1][0].y = p->mRect.top;      p->pt[1][1].x = p->mRect.right ;p->pt[1][1].y = p->mRect.bottom;      p->pt[1][2].x = p->mRect.left+h;p->pt[1][2].y = p->mRect.bottom;      p->pt[1][3].x = p->mRect.left  ;p->pt[1][3].y = (p->mRect.top+p->mRect.bottom)/2;      p->pt[1][4].x = p->mRect.left+h;p->pt[1][4].y = p->mRect.top;      //      for ( int n = 0; n < 5; n++ )        p->pt[1][n].x += p->nShiftMax;      //      }      if ( def.m_queue.setShift.x )        {        ::OffsetRect( &p->mRect, def.m_queue.setShift.x, 0 );        p->bAction = true;        }      break;    case dirDown:      {      p->nShiftMax = Atoi(teg[0].value);      int h = (p->mRect.right-p->mRect.left)/2;      //      p->pt[0][0].x = p->mRect.left                ;p->pt[0][0].y = p->mRect.top;      p->pt[0][1].x = p->mRect.right               ;p->pt[0][1].y = p->mRect.top;      p->pt[0][2].x = p->mRect.right               ;p->pt[0][2].y = p->mRect.bottom-h;      p->pt[0][3].x = (p->mRect.left+p->mRect.right)/2;p->pt[0][3].y = p->mRect.bottom;      p->pt[0][4].x = p->mRect.left                ;p->pt[0][4].y = p->mRect.bottom-h;      //      p->pt[1][0].x = p->mRect.left                ;p->pt[1][0].y = p->mRect.top+h;      p->pt[1][1].x = (p->mRect.left+p->mRect.right)/2;p->pt[1][1].y = p->mRect.top;      p->pt[1][2].x = p->mRect.right               ;p->pt[1][2].y = p->mRect.top+h;      p->pt[1][3].x = p->mRect.right               ;p->pt[1][3].y = p->mRect.bottom;      p->pt[1][4].x = p->mRect.left                ;p->pt[1][4].y = p->mRect.bottom;      //      for ( int n = 0; n < 5; n++ )        p->pt[1][n].y += p->nShiftMax;      //      if ( def.m_queue.setShift.y )        {        ::OffsetRect( &p->mRect, 0, def.m_queue.setShift.y );        p->bAction = true;        }      break;      //      }    };  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~